pragma solidity ^0.8.20;

contract PlainPausableToken {
    address public owner;
    bool public paused;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) private _allowances;

    constructor() { owner = msg.sender; }

    modifier whenNotPaused() { require(!paused, "paused"); _; }

    function pause() external { require(msg.sender == owner, "not owner"); paused = true; }
    function allowance(address o, address s) external view returns (uint256) { return _allowances[o][s]; }
    function approve(address s, uint256 a) external returns (bool) { _allowances[msg.sender][s] = a; return true; }

    function transferFrom(address from, address to, uint256 amount) external whenNotPaused returns (bool) {
        require(_allowances[from][msg.sender] >= amount, "allowance");
        require(balanceOf[from] >= amount, "balance");
        _allowances[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
